original_prompt:
{
  "meta_instruction": {
    "image_category": "cinematic_scene",
    "core_prompt": "A cinematic shot taken from inside a dimly lit blacksmith shop looking outwards towards a partially open rolling shutter. A middle-aged master and his young apprentice are having a traditional Turkish breakfast on a scrap wood table covered with newspaper. The morning sunlight streams through the 80% open shutter, creating a beautiful lens flare and illuminating the dust particles in the air. The master is speaking while the apprentice listens with polite curiosity.",
    "negative_prompt": "clean pristine clothes, spotless environment, modern furniture, soft unworked hands, messy food, overexposed, fully open shutter, artificial studio lighting, cartoonish, 3d render"
  },
  "narrative_and_purpose": {
    "story_or_concept": "A moment of mentorship and tradition. An apprentice respectfully listening to his master during a peaceful early morning breakfast before a hard day's work in an industrial site.",
    "mood_and_vibe": "Authentic, warm, respectful, raw, industrious, serene morning."
  },
  "subjects": [
    {
      "presence": "primary",
      "type": "human",
      "description": "Middle-aged blacksmith master.",
      "dynamic_attributes": {
        "if_human": {
          "role_and_demographics": "Middle-aged male, stubble beard, wearing reading glasses resting on his chest with a neck strap.",
          "emotion_and_expression": "Experienced, calm, speaking with authority and warmth.",
          "action_and_wardrobe": "Wearing slightly dirty mechanic overalls. Hands are clean from dirt but look deeply worn, calloused, and weathered. Sitting and eating breakfast."
        }
      }
    },
    {
      "presence": "primary",
      "type": "human",
      "description": "Young blacksmith apprentice.",
      "dynamic_attributes": {
        "if_human": {
          "role_and_demographics": "Young male, humble appearance.",
          "emotion_and_expression": "Curious, polite, respectful, actively listening.",
          "action_and_wardrobe": "Wearing slightly dirty mechanic overalls. Hands are clean but show signs of manual labor. Sitting at the table, leaning in slightly to listen attentively."
        }
      }
    }
  ],
  "environment_and_worldbuilding": {
    "setting_type": "indoor",
    "location_details": "Inside a gritty mechanic and blacksmith shop in an industrial zone. A metal rolling shutter door is 80% open, revealing the bright morning outside.",
    "time_of_day_and_weather": "Early morning, sunrise, clear weather outside.",
    "props_and_supporting_elements": [
      "Low coffee table made from scrap wood",
      "Newspaper spread as a tablecloth",
      "Chrome plates containing tomatoes, black olives, white feta cheese, and cucumbers",
      "A metal pan of 'menemen' (Turkish scrambled eggs with tomatoes) in the center",
      "A custom trivet under the pan made from welded scrap iron pieces",
      "Metal shavings scattered organically on the shop floor"
    ]
  },
  "camera_and_lens": {
    "shot_scale": "medium_shot",
    "camera_angle": "eye_level",
    "lens_focal_length": "35mm",
    "depth_of_field": "Shallow depth of field, sharp focus on the subjects and the breakfast table, background and outside lightly blurred."
  },
  "lighting_and_atmosphere": {
    "lighting_source": "natural",
    "lighting_quality": "high_contrast",
    "atmospheric_effects": "Morning sun rays streaming into the dark shop, illuminated airborne dust particles, gentle lens flare from the sun."
  },
  "composition_and_layout": {
    "framing_rule": "rule_of_thirds",
    "functional_space": "none"
  },
  "post_processing_and_medium": {
    "medium": "digital_photography",
    "color_grading": "Cinematic color grading, warm earthy tones inside contrasting with the bright morning light outside, subtle teal and orange hues.",
    "texture_and_grain": "Subtle film grain, highly detailed textures on hands, wood, and metal."
  }
}

vi_prompt:
{
  "meta_instruction": {
    "image_category": "cinematic_scene",
    "core_prompt": "Một cảnh quay điện ảnh góc nhìn từ bên trong một xưởng rèn mờ tối nhìn ra ngoài qua cửa cuốn mở hé một phần. Một người thợ cả trung niên và người học việc trẻ tuổi đang dùng bữa sáng truyền thống kiểu Thổ Nhĩ Kỳ trên một chiếc bàn gỗ phế liệu phủ giấy báo. Ánh nắng ban mai rọi xiên qua cánh cửa cuốn mở khoảng 80%, tạo nên hiệu ứng lóe sáng ống kính (lens flare) tuyệt đẹp và làm bừng sáng những hạt bụi lơ lửng trong không khí. Người thợ cả đang nói trong khi người học việc lắng nghe với vẻ tò mò đầy cung kính.",
    "negative_prompt": "quần áo sạch sẽ tinh tươm, môi trường không tì vết, đồ nội thất hiện đại, đôi tay mềm mại chưa từng lao động, đồ ăn bừa bãi, thừa sáng quá mức, cửa cuốn mở toang hoàn toàn, ánh sáng phòng thu nhân tạo, hoạt hình, kết xuất 3d render"
  },
  "narrative_and_purpose": {
    "story_or_concept": "Khoảnh khắc chỉ dạy truyền nghề và tiếp nối truyền thống. Một người học việc chăm chú lắng nghe người thầy của mình trong bữa sáng yên bình vào sáng sớm trước một ngày làm việc vất vả tại một xưởng cơ khí công nghiệp.",
    "mood_and_vibe": "Chân thực, ấm áp, tôn kính, mộc mạc, đậm chất lao động, buổi sáng thanh bình."
  },
  "subjects": [
    {
      "presence": "primary",
      "type": "human",
      "description": "Người thợ rèn bậc thầy tuổi trung niên.",
      "dynamic_attributes": {
        "if_human": {
          "role_and_demographics": "Nam giới trung niên, râu lởm chởm, đeo kính đọc sách vắt trước ngực bằng dây đeo cổ.",
          "emotion_and_expression": "Dày dạn kinh nghiệm, điềm tĩnh, nói chuyện với vẻ uy quyền và ấm áp.",
          "action_and_wardrobe": "Mặc bộ đồ yếm bảo hộ thợ cơ khí hơi lấm lem. Bàn tay đã rửa sạch đất cát nhưng lộ rõ vẻ chai sần, sương gió vì lao động nặng nhọc. Đang ngồi dùng bữa sáng."
        }
      }
    },
    {
      "presence": "primary",
      "type": "human",
      "description": "Cậu học việc thợ rèn trẻ tuổi.",
      "dynamic_attributes": {
        "if_human": {
          "role_and_demographics": "Nam thanh niên trẻ tuổi, vẻ ngoài khiêm tốn.",
          "emotion_and_expression": "Tò mò, lễ phép, tôn kính, chăm chú lắng nghe.",
          "action_and_wardrobe": "Mặc bộ đồ bảo hộ thợ cơ khí hơi bám bẩn. Bàn tay sạch sẽ nhưng có dấu hiệu của lao động chân tay. Ngồi bên bàn, hơi nghiêng người về phía trước để chú ý lắng nghe."
        }
      }
    }
  ],
  "environment_and_worldbuilding": {
    "setting_type": "indoor",
    "location_details": "Bên trong một xưởng cơ khí và rèn kim loại thô mộc tại một khu công nghiệp. Cánh cửa cuốn kim loại mở hé 80%, để lộ buổi sáng rực rỡ bên ngoài.",
    "time_of_day_and_weather": "Sáng sớm, bình minh, thời tiết bên ngoài trong xanh.",
    "props_and_supporting_elements": [
      "Chiếc bàn cà phê thấp làm từ gỗ phế liệu",
      "Tờ báo trải làm khăn bàn",
      "Các đĩa kim loại mạ crom đựng cà chua, quả ô liu đen, phô mai feta trắng và dưa chuột",
      "Một chảo kim loại đựng món 'menemen' (trứng bác cà chua kiểu Thổ Nhĩ Kỳ) ở chính giữa",
      "Một chiếc lót nồi tự chế dưới đáy chảo làm từ các mảnh sắt vụn hàn lại",
      "Vụn kim loại vương vãi tự nhiên trên sàn xưởng"
    ]
  },
  "camera_and_lens": {
    "shot_scale": "medium_shot",
    "camera_angle": "eye_level",
    "lens_focal_length": "35mm",
    "depth_of_field": "Độ sâu trường ảnh nông (shallow depth of field), lấy nét sắc nét vào các nhân vật và bàn ăn sáng, hậu cảnh và quang cảnh bên ngoài mờ nhẹ."
  },
  "lighting_and_atmosphere": {
    "lighting_source": "natural",
    "lighting_quality": "high_contrast",
    "atmospheric_effects": "Các tia nắng ban mai rọi thẳng vào xưởng tối, làm nổi bật các hạt bụi lơ lửng trong không khí, hiệu ứng lóa ống kính dịu nhẹ từ mặt trời."
  },
  "composition_and_layout": {
    "framing_rule": "rule_of_thirds",
    "functional_space": "none"
  },
  "post_processing_and_medium": {
    "medium": "digital_photography",
    "color_grading": "Chỉnh màu điện ảnh (cinematic color grading), các tông màu đất ấm áp bên trong đối lập với ánh sáng ban mai rực rỡ bên ngoài, sắc độ xanh mòng két (teal) và cam (orange) tinh tế.",
    "texture_and_grain": "Hạt phim (film grain) nhẹ nhàng, chi tiết bề mặt cực kỳ sắc nét trên bàn tay, mặt gỗ và kim loại."
  }
}
